#!/usr/bin/env python3
# ARCHIVED 2026-10-29: argmax-capable snapshot of ../rl_switch.py.
# The active submission strategy is ../rl_switch.py, sample mode only.
"""RL-Switch as a standalone Axelrod strategy.

This is a faithful single-file port of the pri_dile candidate
``ipd/policies/candidates/rl_switch.py`` together with
``ipd/policies/meta.py::RLSwitchPolicy``, the standard-library MLP inference
from ``ipd/policies/neural.py`` and its 85-feature extractor.

The strategy uses RL-Wide160 by default.  After at least six rounds, if both
sides have defected at least twice in the first six rounds and the opponent's
latest move is cooperation, it switches to RL-Repair for the rest of the
match.  Both deployable MLP weight sets are embedded below, so this file has
no external data dependencies.

The source candidate is defined for 100-round matches: it cooperates on the
first day, stays cooperative until the opponent's first defection, and defects
on day 100.  This port preserves that horizon.

Usage::

    from rl_switch import RLSwitch

    player = RLSwitch()                 # stochastic "sample" mode
    player = RLSwitch(mode="argmax")    # deterministic variant
    match = axelrod.Match((player, axelrod.TitForTat()), turns=100)
    match.play()

Only the ``axelrod`` package and the Python standard library are required.

Development/evaluation payoff matrix: T=10, R=6, P=1, S=0.
Use the module-level ``GAME`` with axelrod Match/Tournament.
"""
from __future__ import annotations

import base64
import json
import math
import random
import zlib
from operator import mul
from typing import Sequence

from axelrod import Action, Game, Player

# Internal action convention used by the original policy code.
C = 0
D = 1

# Axelrod action objects.
A_C = Action.C
A_D = Action.D

# Development/evaluation payoff matrix: T=10, R=6, P=1, S=0.
GAME = Game(r=6, s=0, t=10, p=1)

FEATURE_VERSION = "ipd-neural-features-v1"
DISPLAY = "RL-Switch"

